/**
 * Add PDF size, PDF icon and download icon
 * to ordinary PDF links inside the ACF Course field.
 *
 * Links already generated by [selected_document]
 * are left unchanged.
 */
function srfti_add_pdf_info_to_course_content( $content ) {

    if ( empty( $content ) ) {
        return '';
    }

    $content = preg_replace_callback(
        '/<a\b([^>]*\bhref=(["\'])([^"\']+\.pdf(?:\?[^"\']*)?)\2[^>]*)>(.*?)<\/a>/is',
        function ( $matches ) {

            $attributes = $matches[1];
            $file_url   = html_entity_decode( $matches[3] );
            $link_text  = $matches[4];


            /*
             * IMPORTANT:
             * Do not process links already created by
             * the [selected_document] shortcode.
             */
            if (
                strpos( $attributes, 'pdf-download-link' ) !== false ||
                strpos( $link_text, 'pdf-icon' ) !== false
            ) {
                return $matches[0];
            }


            /*
             * Try to find the WordPress Media attachment.
             */
            $attachment_id = attachment_url_to_postid(
                $file_url
            );


            /*
             * Older links may use HTTP while
             * the site currently uses HTTPS.
             */
            if ( ! $attachment_id ) {

                $https_url = set_url_scheme(
                    $file_url,
                    'https'
                );

                $attachment_id = attachment_url_to_postid(
                    $https_url
                );
            }


            $file_path = '';


            /*
             * Get attachment file path.
             */
            if ( $attachment_id ) {

                $file_path = get_attached_file(
                    $attachment_id
                );
            }


            /*
             * Fallback for uploaded files that
             * attachment_url_to_postid() cannot resolve.
             */
            if (
                ! $file_path ||
                ! file_exists( $file_path )
            ) {

                $upload_dir = wp_upload_dir();

                $file_url_path = wp_parse_url(
                    $file_url,
                    PHP_URL_PATH
                );

                $upload_url_path = wp_parse_url(
                    $upload_dir['baseurl'],
                    PHP_URL_PATH
                );


                if (
                    $file_url_path &&
                    $upload_url_path &&
                    strpos(
                        $file_url_path,
                        $upload_url_path
                    ) === 0
                ) {

                    $relative_path = substr(
                        $file_url_path,
                        strlen( $upload_url_path )
                    );

                    $file_path =
                        $upload_dir['basedir'] .
                        $relative_path;
                }
            }


            /*
             * Get file size.
             */
            $file_size = '';


            if (
                $file_path &&
                file_exists( $file_path )
            ) {

                $bytes = filesize(
                    $file_path
                );


                if ( false !== $bytes ) {

                    $file_size = size_format(
                        $bytes,
                        2
                    );
                }
            }


            /*
             * Add pdf-download-link class.
             */
            $attributes = trim(
                $attributes
            );


            if (
                preg_match(
                    '/\bclass=(["\'])(.*?)\1/i',
                    $attributes
                )
            ) {

                $attributes = preg_replace(
                    '/\bclass=(["\'])(.*?)\1/i',
                    'class=$1$2 pdf-download-link$1',
                    $attributes
                );

            } else {

                $attributes .=
                    ' class="pdf-download-link"';
            }


            /*
             * Open PDF in a new tab.
             */
            if (
                ! preg_match(
                    '/\btarget=/i',
                    $attributes
                )
            ) {

                $attributes .=
                    ' target="_blank"';
            }


            /*
             * Security for target="_blank".
             */
            if (
                ! preg_match(
                    '/\brel=/i',
                    $attributes
                )
            ) {

                $attributes .=
                    ' rel="noopener noreferrer"';
            }


            /*
             * Build final link.
             *
             * Note:
             * We show only the file size.
             * The visible word "PDF" is not added here.
             */
            return
                '<a ' . $attributes . '>' .

                    $link_text .

                    ' <span class="pdf-icon" aria-hidden="true"></span>' .

                    (
                        $file_size
                        ? ' <span class="file-size">(' .
                            esc_html( $file_size ) .
                          ')</span>'
                        : ''
                    ) .

                    ' <span class="download-icon" aria-hidden="true"></span>' .

                    ' <span class="sr-only">' .
                        esc_html__(
                            'Download PDF, opens in a new tab',
                            'srft-theme'
                        ) .
                    '</span>' .

                '</a>';
        },
        $content
    );


    return $content;
}
