                    );


                    if ( $course_content ) {

                        /*
                         * First execute shortcodes such as:
                         *
                         * [selected_document id="8654"]
                         */
                        $course_content = do_shortcode(
                            $course_content
                        );


                        /*
                         * Then process only ordinary PDF links.
                         *
                         * Links created by selected_document
                         * already have pdf-download-link and
                         * will therefore be skipped.
                         */
                        $course_content =
                            srfti_add_pdf_info_to_course_content(
                                $course_content
                            );


                        echo wp_kses_post(
                            $course_content
                        );
                    }

